{"@type":"Question","name":"Do you waterproof before tiling showers?","acceptedAnswer":{"@type":"Answer","text":"Always — we use Schluter waterproofing systems and real grout so showers never leak."}},
{"@type":"Question","name":"Can you match or repair existing tile?","acceptedAnswer":{"@type":"Answer","text":"We can in many cases; we will assess matching options during your consultation."}},
{"@type":"Question","name":"Do you do heated tile floors?","acceptedAnswer":{"@type":"Answer","text":"Yes — heated floors are a popular upgrade in primary baths."}}
]}

